%[text] # Week 11 Solution: Transient Heat Equation — Quadratic Elements, Backward Euler
%[text] This script solves the 1D transient heat equation using **quadratic (second-order)** elements and **backward Euler** (implicit) time integration with a **consistent mass** matrix.
%%
%[text] ## 0) Problem Statement
%[text] We solve the transient heat equation:
%[text]{"align":"center"} $ \\frac{\\partial u}{\\partial t} = \\frac{\\partial^2 u}{\\partial x^2}, \\quad x \\in (0,1),; t \> 0 $
%[text] with homogeneous Dirichlet boundary conditions $ u(0,t) = u(1,t) = 0 $ and initial condition $ u(x,0) = \\sin(\\pi x) $.
%[text] The exact solution is $ u(x,t) = e^{-\\pi^2 t}\\sin(\\pi x) $.

L       = 1.0;
t_final = 0.1;

u_exact = @(x,t) exp(-pi^2*t) .* sin(pi*x);
u_init  = @(x) sin(pi*x);

x_plot = linspace(0, L, 300);
figure %[output:870d4b1f]
plot(x_plot, u_init(x_plot), 'LineWidth', 1.8); %[output:870d4b1f]
grid on; xlabel('x'); ylabel('u(x,0)'); %[output:870d4b1f]
title('Initial Condition: u(x,0) = sin(\pi x)'); %[output:870d4b1f]
%%
%[text] ## 1) Semi-Discrete Weak Form
%[text] Multiply by test function $ v $, integrate by parts:
%[text]{"align":"center"} $ \\int\_0^1 \\frac{\\partial u}{\\partial t},v,dx + \\int\_0^1 \\frac{\\partial u}{\\partial x}\\frac{\\partial v}{\\partial x},dx = 0 $
%[text] This yields the semi-discrete system $ M,\\dot{U} + K,U = 0 $.
%%
%[text] ## 2) Quadratic Basis Functions
%[text] Three-node reference element on $ \\xi \\in \[-1,1\] $:
%[text]{"align":"center"} $ N\_1(\\xi)=\\frac{1}{2}\\xi(\\xi-1),\\quad N\_2(\\xi)=1-\\xi^2,\\quad N\_3(\\xi)=\\frac{1}{2}\\xi(\\xi+1) $

syms xi_s real
N1s = xi_s*(xi_s - 1)/2;
N2s = 1 - xi_s^2;
N3s = xi_s*(xi_s + 1)/2;
N   = [N1s; N2s; N3s];

xi_num = linspace(-1, 1, 200);
figure %[output:8cb30a46]
plot(xi_num, double(subs(N1s, xi_s, xi_num)), 'LineWidth', 1.8); hold on; %[output:8cb30a46]
plot(xi_num, double(subs(N2s, xi_s, xi_num)), 'LineWidth', 1.8); %[output:8cb30a46]
plot(xi_num, double(subs(N3s, xi_s, xi_num)), 'LineWidth', 1.8); %[output:8cb30a46]
grid on; xlabel('\xi'); ylabel('Value'); %[output:8cb30a46]
title('Quadratic Basis Functions'); %[output:8cb30a46]
legend('N_1 (left)', 'N_2 (mid)', 'N_3 (right)', 'Location', 'bestoutside'); %[output:8cb30a46]
%%
%[text] ## 3) Element Matrices — Symbolic Derivation
%[text] **Stiffness (3x3):** $ k\_{ab}^{(e)} = \\int\_{-1}^{1} \\frac{dN\_a}{dx}\\frac{dN\_b}{dx},J,d\\xi $
%[text] **Consistent mass (3x3):** $ m\_{ab}^{(e)} = \\int\_{-1}^{1} N\_a,N\_b,J,d\\xi $
%[text] The implicit scheme uses the **consistent** mass matrix. Backward Euler is **unconditionally stable**.

syms h_e positive
J    = h_e/2;
dNdx = (1/J) * diff(N, xi_s);

ke_sym = sym(zeros(3));
me_sym = sym(zeros(3));
for a = 1:3
    for b = 1:3
        ke_sym(a,b) = int(dNdx(a)*dNdx(b)*J, xi_s, -1, 1);
        me_sym(a,b) = int(N(a)*N(b)*J, xi_s, -1, 1);
    end
end
ke_sym = simplify(ke_sym) %[output:7e88bb30]
me_sym = simplify(me_sym) %[output:4a9676d4]
%%
%[text] ## 4) Assembly
%[text] With $ n\_{el} $ quadratic elements the total node count is $ 2 n\_{el}+1 $.

nel     = 10;
nn      = 2*nel + 1;
x_nodes = linspace(0, L, nn).';
conn    = [(1:2:2*nel-1).', (2:2:2*nel).', (3:2:2*nel+1).'];

K = zeros(nn);
M = zeros(nn);

for e = 1:nel
    nd = conn(e,:);
    he = x_nodes(nd(3)) - x_nodes(nd(1));

    ke = (1/(3*he)) * [ 7 -8  1;
                       -8 16 -8;
                        1 -8  7];
    me = (he/30) * [ 4  2 -1;
                     2 16  2;
                    -1  2  4];

    K(nd, nd) = K(nd, nd) + ke;
    M(nd, nd) = M(nd, nd) + me;
end

figure; spy(K); %[output:5f3e74df]
xlabel('j'); ylabel('i'); %[output:5f3e74df]
title('Stiffness K — sparsity (quadratic)'); %[output:5f3e74df]
%%
%[text] ## 5) Initial Condition

U = u_init(x_nodes);
U(1) = 0; U(end) = 0;
%%
%[text] ## 6) Backward Euler Time Integration
%[text]{"align":"center"} $ (M + \\Delta t,K),U^{n+1} = M,U^n $
%[text] The matrix $ A = M + \\Delta t,K $ is factored once; each step is a back-substitution.

dt = 0.01;
Nt = round(t_final / dt);

A = M + dt * K;
A(1,:) = 0;   A(1,1)     = 1;
A(end,:) = 0; A(end,end) = 1;

t_snap = [0, t_final/2, t_final];
U_snap = zeros(nn, numel(t_snap));
U_snap(:,1) = U;
snap_idx = 2;

for n = 1:Nt
    tn  = n * dt;
    rhs = M * U;
    rhs(1) = 0;  rhs(end) = 0;
    U = A \ rhs;

    if snap_idx <= numel(t_snap) && tn >= t_snap(snap_idx) - dt/2
        U_snap(:,snap_idx) = U;
        snap_idx = snap_idx + 1;
    end
end
%%
%[text] ## 7) Validation

figure; hold on; %[output:62728ab0]
colors = lines(numel(t_snap));
leg = {};
for k = 1:numel(t_snap)
    plot(x_nodes, U_snap(:,k), 'o-', 'Color', colors(k,:), ... %[output:62728ab0]
         'LineWidth', 1.5, 'MarkerSize', 4); %[output:62728ab0]
    fplot(@(x) u_exact(x, t_snap(k)), [0 L], '--', ...
         'Color', colors(k,:), 'LineWidth', 1.8);
    leg{end+1} = sprintf('FEM  t=%.3f', t_snap(k));
    leg{end+1} = sprintf('Exact t=%.3f', t_snap(k));
end
grid on; xlabel('x'); ylabel('u(x,t)'); %[output:62728ab0]
title('Backward Euler — Quadratic Elements'); %[output:62728ab0]
legend(leg, 'Location', 'best'); %[output:62728ab0]

err = max(abs(U - u_exact(x_nodes, t_final)));
fprintf('Max nodal error at t=%.2f: %.4e\n', t_final, err); %[output:5769abf3]

